from django.shortcuts import render
from django.core.cache import cache
from django.views.decorators.cache import cache_page
from django.db.models.signals import post_save, post_delete
from django.dispatch import receiver
from monapp.models import Article

@cache_page(600)
def liste_articles(request):
    articles = Article.objects.select_related('auteur').prefetch_related('tags').all()
    return render(request, 'articles/liste.html', {'articles': articles})

@receiver([post_save, post_delete], sender=Article)
def invalider_cache_articles(sender, instance, **kwargs):
    cache.delete('views.decorators.cache.cache_page..liste_articles')
